import { useRef } from "react";
import { Input } from "../components/Input";
import { BACKEND_URL } from "../config";
import axios from "axios";
import { useNavigate } from "react-router-dom";
import DottedButton from "../components/DottedButton"; // Ensure the path is correct

export function Signin() {
    const usernameRef = useRef<HTMLInputElement>(null);
    const passwordRef = useRef<HTMLInputElement>(null);
    const navigate = useNavigate();

    async function signin() {
        const username = usernameRef.current?.value;
        const password = passwordRef.current?.value;

        if (!username || !password) {
            alert("Please fill in both fields.");
            return;
        }

        try {
            const response = await axios.post(BACKEND_URL + "/api/v1/signin", {
                username,
                password
            });

            const jwt = response.data.token;
            localStorage.setItem("token", jwt);
            navigate("/dashboard");
        } catch (err) {
            alert("Invalid credentials or server error.");
        }
    }

    return (
        <div className="h-screen w-screen bg-gray-100 flex justify-center items-center px-4">
            <div className="bg-white rounded-2xl shadow-lg border border-gray-300 w-full max-w-sm p-8">
                <h2 className="text-2xl font-bold mb-6 text-center text-gray-800">Sign in</h2>

                <Input reference={usernameRef} placeholder="Username" />
                <div className="h-4" />
                <Input reference={passwordRef} placeholder="Password" type="password" />

                <div className="pt-6 flex justify-center">
                    <div onClick={signin}>
                        <DottedButton />
                    </div>
                </div>
            </div>
        </div>
    );
}
